func TestGcdOfTwelveAndEighteenIsSix(emonT *testing.T) {
	port.AssertEq(emonT, hello.Gcd(12, 18), 6, "gcd(12,18)")
	port.AssertEq(emonT, hello.Gcd(42, 63), 21, "gcd(42,63)")
}

func TestGcdWithZeroIsTheOther(emonT *testing.T) {
	port.AssertEq(emonT, hello.Gcd(0, 9), 9, "gcd(0,9)")
	port.AssertEq(emonT, hello.Gcd(9, 0), 9, "gcd(9,0)")
}

func TestAHexBlobReadsBigEndian(emonT *testing.T) {
	port.AssertEq(emonT, port.BlobU16(port.HexBlob("80 ff"), 0), 33023, "u16 of 80ff")
}

func TestARowLoopNamesItsRow(emonT *testing.T) {
	var i int32 = 0
	for i < 3 {
		port.AssertEqAt(emonT, hello.Gcd(i+1, 1), 1, "gcd(n,1)", i)
		i += 1
	}
}

func TestATextSinkComparesWithALiteral(emonT *testing.T) {
	var t *strings.Builder = port.NewText()
	port.TextAscii(t, "n=")
	port.TextI32(t, 42)
	port.AssertText(emonT, t, "n=42", "text")
	port.AssertThat(emonT, 1 < 2, "one is less than two")
}

func Test32BitShiftsLoseBitsOffTheTopAndKeepTheSign(emonT *testing.T) {
	// Operands are LOCALS: Go folds a constant shift at compile time and
	// refuses `1 << 31` as an int32 overflow, where a variable wraps.
	var one int32 = 1
	var three int32 = 3
	var neg int32 = -16
	port.AssertEq(emonT, (one)<<uint(4), 16, "1 << 4")
	port.AssertEq(emonT, (one)<<uint(31), -2147483648, "1 << 31 is the sign bit")
	port.AssertEq(emonT, (three)<<uint(30), -1073741824, "3 << 30 drops the top bit")
	port.AssertEq(emonT, (neg)>>uint(2), -4, "arithmetic right shift keeps the sign")
	port.AssertEq(emonT, (4096)>>uint(12), 1, "4096 >> 12")
}
